var t=`0900-garudhiya`;var n=`world-0900`;var a=`MV`;var o=`south-asia`;var s=4;var r=61;var l={en:`Garudhiya`,ua:`Гарудія`};var u={en:`Garudhiya is a Maldives dish made with yellowfin tuna, yellow onion, garlic, serrano pepper. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Гарудія, страва кухні країни Мальдіви. Основні складники: жовтоперий тунець, жовта цибуля, часник, перець серрано. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 22 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 22 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:22,i:[[`yellowfin-tuna`,720,`g`],[`water`,1150,`ml`],[`yellow-onion`,130,`g`],[`garlic`,3,`clove`],[`table-salt`,null,`to_taste`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 14 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 14 хвилин до м’якості та готовності.`,t:[`simmering`],m:14,i:[[`serrano-pepper`,2,`pcs`],[`black-peppercorn`,4,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`white-rice`,340,`g`],[`water`,640,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var m={slug:t,id:n,country:`MV`,region:o,servings:4,minutes:61,title:l,text:u,steps:d};export{a as country,m as default,n as id,r as minutes,o as region,s as servings,t as slug,d as steps,u as text,l as title};